SEED_DEALS = SEED_DEALS_V1 + SEED_DEALS_V2


_LOCK_PATH = os.path.join(tempfile.gettempdir(), "dealflow-seed.lock")
_LOCK_FD = open(_LOCK_PATH, "w")


def _norm(text):
    return (text or "").strip().lower()


def _existing_keys(path):
    """(name, location) pairs and source_urls already in the database."""
    names, urls = set(), set()
    for deal in records.list_deals(path=path):
        names.add((_norm(deal["name"]), _norm(deal["location"])))
        url = (deal["contact"].get("source_url") or "").strip()
        if url:
            urls.add(url)
    return names, urls


def seed_database(path=None):
    """Insert any missing seed deals. Returns the new Deal IDs.

    Safe to call on every boot: existing deals are detected by
    name + location or source_url and skipped.
    """
    fcntl.flock(_LOCK_FD, fcntl.LOCK_EX)
    try:
        names, urls = _existing_keys(path)
        inserted = []
        for seed in SEED_DEALS:
            key = (_norm(seed["name"]), _norm(seed["location"]))
            if key in names:
                continue
            if seed["source_url"] and seed["source_url"] in urls:
                continue
            raw = {k: seed[k] for k in (
                "name", "asset_type", "location", "purchase_price",
                "source", "source_url", "notes")}
            deal_id = records.submit_deal(raw, path)
            if seed["seed_status"] == "PURSUE":
                records.set_status(deal_id, "REVIEWING", path)
                records.set_status(deal_id, "PURSUE", path)
            inserted.append(deal_id)
            names.add(key)
            if seed["source_url"]:
                urls.add(seed["source_url"])
        return inserted
    finally:
        fcntl.flock(_LOCK_FD, fcntl.LOCK_UN)


if __name__ == "__main__":
    ids = seed_database()
    print("seeded %d deals" % len(ids))
    for deal_id in ids:
        print(" ", deal_id)
